package com.mfg.qms.entity;import jakarta.persistence.*;import lombok.*;import java.math.*;import java.time.*;
@Entity @Table(name="qms_inspection",catalog="src_qms") @Getter @Setter @NoArgsConstructor public class Inspection{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="inspection_no")private String inspectionNo;@Column(name="inspection_type")private String inspectionType;@Column(name="material_code")private String materialCode;@Column(name="material_name")private String materialName;@Column(name="batch_no")private String batchNo;@Column(name="prod_order_no")private String prodOrderNo;@Column(name="work_order_no")private String workOrderNo;@Column(name="inspected_qty")private BigDecimal inspectedQty;@Column(name="qualified_qty")private BigDecimal qualifiedQty;@Column(name="defect_qty")private BigDecimal defectQty;@Column(name="defect_rate")private BigDecimal defectRate;@Column(name="inspect_result")private String result="PENDING";@Column(name="inspect_date")private LocalDate inspectDate;@Column(name="inspector_code")private String inspectorCode;}
